using System;using System.IO;using UnityEditor;using UnityEngine;
public static class BuildBatchEleven {
 public static void Verify(){try{var b=AssetBundle.LoadFromFile(Path.GetFullPath("../Bundle/batcheleven.unity3d"));if(b==null)throw new Exception("Bundle load");var g=b.LoadAsset<GameObject>("delveSealedIronboundCrate");if(g==null||g.tag!="T_Block"||g.GetComponent<BoxCollider>().size!=Vector3.one)throw new Exception("Crate interaction tag/collider");int braces=0;foreach(Transform t in g.transform)if(t.name.Contains("Crossboard"))braces++;if(braces!=8)throw new Exception("Four-sided seal");var clip=b.LoadAsset<AudioClip>("delveMagicRechargeWhoosh");if(clip==null||clip.length<1.2f)throw new Exception("Audio duration");clip.LoadAudioData();var samples=new float[clip.samples*clip.channels];if(!clip.GetData(samples,0))throw new Exception("Audio data");double sum=0;foreach(var x in samples)sum+=x*x;if(Math.Sqrt(sum/samples.Length)<.01)throw new Exception("Silent clip");File.WriteAllText("../asset-validation.txt","PASS: bundle reload, tagged 1m collider, 8 crossboards, audible 1.3-second recharge clip");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static Material wood,brace,iron;
 static Material Mat(string n,Color c){var m=new Material(Shader.Find("Standard"));m.name=n;var t=new Texture2D(64,64);for(int y=0;y<64;y++)for(int x=0;x<64;x++)t.SetPixel(x,y,c*(.8f+.3f*Mathf.PerlinNoise(x*.27f,y*.05f)));t.Apply();AssetDatabase.CreateAsset(t,"Assets/Generated/"+n+"Tex.asset");m.mainTexture=t;AssetDatabase.CreateAsset(m,"Assets/Generated/"+n+".mat");return m;}
 static void Part(GameObject root,string n,Vector3 p,Vector3 s,Material m,Vector3 rot){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(root.transform,false);g.transform.localPosition=p;g.transform.localScale=s;g.transform.localEulerAngles=rot;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
 public static void Run(){try{Directory.CreateDirectory("Assets/Generated");Directory.CreateDirectory("../Bundle");Directory.CreateDirectory("../Preview");wood=Mat("Oak",new Color(.31f,.19f,.085f));brace=Mat("FreshSealBoards",new Color(.57f,.36f,.16f));iron=Mat("Iron",new Color(.13f,.14f,.13f));var tags=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);var arr=tags.FindProperty("tags");bool found=false;for(int k=0;k<arr.arraySize;k++)if(arr.GetArrayElementAtIndex(k).stringValue=="T_Block")found=true;if(!found){arr.InsertArrayElementAtIndex(arr.arraySize);arr.GetArrayElementAtIndex(arr.arraySize-1).stringValue="T_Block";tags.ApplyModifiedProperties();}var g=new GameObject("delveSealedIronboundCrate");g.tag="T_Block";
  for(int i=0;i<6;i++){float h=(i+.5f)/6;for(int side=-1;side<=1;side+=2){Part(g,"Side",new Vector3(side*.475f,h,0),new Vector3(.04f,.162f,.95f),wood,Vector3.zero);Part(g,"End",new Vector3(0,h,side*.475f),new Vector3(.95f,.162f,.04f),wood,Vector3.zero);}for(int side=-1;side<=1;side+=2)Part(g,"Lid",new Vector3((i-2.5f)/6,.5f+side*.48f,0),new Vector3(.162f,.04f,.96f),wood,Vector3.zero);}
  foreach(float x in new[]{-.35f,.35f})for(int side=-1;side<=1;side+=2){Part(g,"Band",new Vector3(x,.5f,side*.49f),new Vector3(.055f,1,.02f),iron,Vector3.zero);Part(g,"SideBand",new Vector3(side*.49f,.5f,x),new Vector3(.02f,1,.055f),iron,Vector3.zero);}
  for(int side=-1;side<=1;side+=2)foreach(float angle in new[]{45f,-45f}){Part(g,"SealedCrossboard",new Vector3(0,.5f,side*.505f),new Vector3(.115f,1.16f,.035f),brace,new Vector3(0,0,angle));Part(g,"SideCrossboard",new Vector3(side*.505f,.5f,0),new Vector3(.035f,1.16f,.115f),brace,new Vector3(angle,0,0));}
  var collider=g.AddComponent<BoxCollider>();collider.center=new Vector3(0,.5f,0);collider.size=Vector3.one;string prefab="Assets/Generated/delveSealedIronboundCrate.prefab";PrefabUtility.SaveAsPrefabAsset(g,prefab);
  int sr=44100,len=(int)(sr*1.3f);var samples=new float[len];var rng=new System.Random(71);float low=0;for(int i=0;i<len;i++){float t=i/(float)len;low=.78f*low+.22f*((float)rng.NextDouble()*2-1);float env=Mathf.Pow(Mathf.Sin(t*Mathf.PI),1.5f);samples[i]=env*(low*.75f+Mathf.Sin(2*Mathf.PI*(220*t+180*t*t))*.025f);}
  var clip=AudioClip.Create("delveMagicRechargeWhoosh",len,1,sr,false);clip.SetData(samples,0);using(var bw=new BinaryWriter(File.Create("Assets/Generated/delveMagicRechargeWhoosh.wav"))){bw.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));bw.Write(36+len*2);bw.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));bw.Write(16);bw.Write((short)1);bw.Write((short)1);bw.Write(sr);bw.Write(sr*2);bw.Write((short)2);bw.Write((short)16);bw.Write(System.Text.Encoding.ASCII.GetBytes("data"));bw.Write(len*2);foreach(float sample in samples)bw.Write((short)(sample*32767));}AssetDatabase.ImportAsset("Assets/Generated/delveMagicRechargeWhoosh.wav",ImportAssetOptions.ForceSynchronousImport);AssetDatabase.SaveAssets();
  RenderSettings.ambientLight=Color.gray;var light=new GameObject("Key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.5f;light.transform.rotation=Quaternion.Euler(35,-20,0);var cam=new GameObject("Camera").AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=.85f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.clear;cam.transform.position=new Vector3(2,1.8f,-3);cam.transform.LookAt(new Vector3(0,.5f,0));var rt=new RenderTexture(512,512,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var img=new Texture2D(512,512,TextureFormat.RGBA32,false);img.ReadPixels(new Rect(0,0,512,512),0,0);img.Apply();File.WriteAllBytes("../Preview/sealed-crate.png",img.EncodeToPNG());
  var build=new AssetBundleBuild{assetBundleName="batcheleven.unity3d",assetNames=new[]{prefab,"Assets/Generated/delveMagicRechargeWhoosh.wav"},addressableNames=new[]{"delveSealedIronboundCrate","delveMagicRechargeWhoosh"}};if(BuildPipeline.BuildAssetBundles("../Bundle",new[]{build},BuildAssetBundleOptions.ChunkBasedCompression,BuildTarget.StandaloneWindows64)==null)throw new Exception("Bundle failed");File.WriteAllText("../result.txt","PASS sealed crate crossboards and synthesized magic recharge whoosh");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("../result.txt","FAIL "+e);Debug.LogException(e);EditorApplication.Exit(1);}}
}
